"""Public aggregate report from verified frozen results; never fits or reads patient data."""
import json
from pathlib import Path
root=Path(__file__).parent;r=json.loads((root/'results/results.json').read_text());v=json.loads((root/'results/VERIFICATION.json').read_text());assert v['state']=='PASS';p=r[0];m=p['metrics'];cfg=json.loads((root/'config.json').read_text());names={'cls768_ridge':'CLS ridge','scale_joint':'尺度联合头','df_matched_joint':'df匹配联合头','plain_correction':'完整普通修正','utility_correction':'原修复＋保留','score_selector':'仅分数选择器','support_selector':'分数＋原型支持选择器'}
lines=['# 最终20类选择器：支持信息带来开发集增益，尚未达到强联合头的尾类保护','', '本轮已完成并独立验收PASS。**支持选择器总体BA最高，三个外层折均超过完整普通修正；仅分数的净增益很小。两者都部分减少完整修正的尾类损失和CLS加权损害，但仍未达到两个强联合头的保护水平，不能宣布全面成功。**','', '## 汇总结果','', '| 方法 | BA% | 类别/患者等权PP% | 尾类BA% | 相对CLS的BA加权损害（百分点） |','|---|---:|---:|---:|---:|']
for a,z in m.items():
 harm=p['contrasts'].get(a+'-cls768_ridge',{}).get('BA_harm',0)*100;lines.append(f"| {names[a]} | {100*z['BA']:.4f} | {100*z['PP_accuracy']:.4f} | {100*z['frequency_BA']['tail']:.4f} | {harm:.4f} |")
lines+=['','PP是类别等权、类内患者等权的图片正确性，不是病例级分类。CLS损害指CLS原本正确、候选错误样本的类别等权质量；不是原始张数或总错误率。','', '## 主要判断','', '分数＋原型支持相对完整普通修正：BA +0.3903个百分点、尾类BA +3.0424个百分点、CLS加权损害下降1.0439个百分点。相对仅分数：BA +0.3655个百分点。它还比原修复＋保留高0.2246个百分点。','', '但相对df强联合头，支持方案的尾类BA仍低3.0798个百分点，CLS损害仍高0.5522个百分点；相对尺度联合头分别低2.6091、高0.5186个百分点。因此支持“得到更好的总体—保护折中”，不支持“同时超过强联合头的总体与保护能力”。','', '仅分数相对普通修正仅+0.0248个百分点，低于原修复＋保留0.1408个百分点；主要价值是部分保护，不能称为可靠的性能突破。','', '## 三折一致性','', '| 外层折 | 完整普通BA% | 仅分数BA% | 支持BA% | 支持相对普通（百分点） |','|---|---:|---:|---:|---:|']
for z in r[1:]:
 mm=z['metrics'];lines.append(f"| {z['scope']} | {100*mm['plain_correction']['BA']:.4f} | {100*mm['score_selector']['BA']:.4f} | {100*mm['support_selector']['BA']:.4f} | {100*(mm['support_selector']['BA']-mm['plain_correction']['BA']):+.4f} |")
lines+=['','支持方案三折BA和尾类均高于普通修正、CLS损害均低于普通修正；总体也均高于两个强联合头及原修复＋保留。每折尾类仍低于两个强联合头，CLS加权损害仍高于两个强联合头。方向一致不等于统计显著；外层结果已多次参与研究设计，本轮不是独立最终测试。','', '## 拒绝损害是否超过丢掉救回','', '固定B=df联合、F=完整普通修正。以下为全体样本类别等权BA质量，不是仅在分歧集合内部重新归一的比例。','', '| 选择器 | 避免F对B的损害（百分点） | 丢掉F对B的救回（百分点） | 净BA变化（百分点） |','|---|---:|---:|---:|']
for a in ['score_selector','support_selector']:
 c=p['contrasts'][a+'-plain_correction'];lines.append(f"| {names[a]} | {100*c['BA_rescue']:.4f} | {100*c['BA_harm']:.4f} | {100*c['delta_BA']:+.4f} |")
lines+=['','支持方案避免1.8595个百分点损害，同时丢掉1.4692个百分点救回，净+0.3903。仅分数两项几乎抵消。注意原始张数：支持方案相对F恢复192张、失去1229张，但类别等权净收益仍为正，不能用张数差代替BA。','', '这给出有限但有用的证据：在当前嵌套开发设置中，训练原型支持与分数联合使用可以更好地区分采用F的收益与损害。不能据此证明原型距离是唯一原因、已识别普适风险，或新增patch信息被单独识别；F中也含CLS判别修正。','', '## 尾类与联合独有纠正','', '| 原类别 | 图片数 | df联合正确 | 完整普通正确 | 仅分数正确 | 支持正确 |','|---|---:|---:|---:|---:|---:|']
for c in cfg['frequency_bins']['tail']:
 i=cfg['order'].index(c);lines.append(f"| {c} | {m['cls768_ridge']['counts'][i]} | {m['df_matched_joint']['correct_by_class'][i]} | {m['plain_correction']['correct_by_class'][i]} | {m['score_selector']['correct_by_class'][i]} | {m['support_selector']['correct_by_class'][i]} |")
lines+=['','两个选择器消除了普通修正在类14和16上的新增零召回，但类16仍仅1/32，df为4/32；类14支持6/59、df为8/59。原类别15全部方法仍为0/7，是既有失败，不是选择器新增损害。支持方案在六个有非零df召回的尾类上仍全部低于df。','', '尺度联合相对CLS独有纠正共2119张：普通修正保留1878张，仅分数1932张，支持1934张。其类别等权正确质量分别为2.2692、2.6900、2.8347个百分点，仍低于尺度联合完整的3.6424。不能只凭这部分恢复宣称patch独有增益完整保留。','', '## 隔离、验收与成本','', '复用68058张训练图片的1536维缓存（768 CLS＋768 patch），新编码0。3个外层患者折、外层训练内部两折互换。新拟合9次ridge（3单折df＋6温度教师）、3个单折plain残差、6个选择器；外层基础头不重训。BA权重用于选择器；基础头保留原类别/患者权重。两个输入方案固定，没有超参/阈值搜索。','', '6个选择器全部封存后才读取旧外层预测并生成新选择。更深温度教师的两个训练子集缺原类别15，按冻结20列零目标规则处理并保留覆盖记录。少样本单折教师到两折外层模型的分布差异仍可能限制选择器迁移，本轮未单独隔离这一因素。','', f"独立验收重算{v['predictions_recomputed']}条新预测、{v['metric_records']}组指标；分数、特征、指标最大差均为0，概率差{v['max_probability_error']:.2e}。复核全部温度教师与基础头正规方程、df匹配、残差目标/梯度、选择器标签/标准化/目标梯度、患者隔离和历史预测一致性。无失败、无重试。",'',f"worker实测{v['worker_costs']['process_wall_seconds']:.3f}秒，独立验收实测{v['verification_seconds']:.3f}秒，工程检查{cfg['engineering_seconds']:.3f}秒；累计可记录时间{cfg['prior_recorded_seconds']+cfg['engineering_seconds']+v['worker_costs']['process_wall_seconds']+v['verification_seconds']:.3f}秒。历史未记录开销仍标为缺失，不伪补。CPU4，GPU0；worker峰值RSS约{v['worker_costs']['RSS_peak_bytes']/2**30:.3f}GiB，核验约{v['verification_RSS_peak_bytes']/2**30:.3f}GiB。",'',f"核验时相关四轮远程总文件量{v['output_bytes_combined']/1e6:.3f}MB，另预留100MB本地/中性源码，远低于20GB新增空间限制；未复制特征缓存或删除历史证据。",'', '## 研究结论与停止','', '本轮得到一个正向开发结果：分数之外加入固定训练原型支持，带来三折一致的总体增益及部分保护。但尾类和CLS损害仍未达到强联合头，原定全面性能目标尚未完成。保留该候选作为可迁移支持信号的初步证据，不扩展六阶段、不追加模块或搜索。后续需重新授权；本次只完成结果分析与公开交付。','', '交付源码、冻结配置、匿名聚合指标与成本；不公开患者标识、逐样本分数、缓存、模型或原始日志。']
(root/'REPORT_ZH.md').write_text('\n'.join(lines)+'\n')
